namespace AgentRouter.Core.Contracts.Configuration;

/// <summary>
/// An ordered fallback chain exposed to Claude Code as a synthetic model id. When a target fails
/// before producing useful content, the chain advances to the next configured target.
/// </summary>
public sealed class ModelFallbackChain
{
    /// <summary>Stable internal id generated by the app.</summary>
    public string Id { get; set; } = string.Empty;

    /// <summary>Human-readable name shown in the panel and model picker.</summary>
    public string Name { get; set; } = string.Empty;

    /// <summary>CLI/model slug. <c>ccg --&lt;slug&gt;</c> launches only this chain.</summary>
    public string Slug { get; set; } = string.Empty;

    public bool Enabled { get; set; } = true;

    public RoutingStrategy RoutingStrategy { get; set; } = RoutingStrategy.Waterfall;

    /// <summary>Attempts for the initially selected target before moving to another target.</summary>
    public int PrimaryAttempts { get; set; } = 2;

    /// <summary>Time to wait for provider response headers on each attempt.</summary>
    public int RequestTimeoutMs { get; set; } = 60_000;

    /// <summary>First-token timeout. No useful content before this advances the chain.</summary>
    public int StreamIdleTimeoutMs { get; set; } = 30_000;

    /// <summary>Maximum stream lifetime for each attempt.</summary>
    public int StreamTotalTimeoutMs { get; set; } = 60_000;

    /// <summary>Ordered fallback targets. Order is user-defined priority.</summary>
    public List<ModelFallbackTarget> Models { get; set; } = new();
}

/// <summary>One provider/model pair inside a <see cref="ModelFallbackChain"/>.</summary>
public sealed class ModelFallbackTarget
{
    public string ProviderId { get; set; } = string.Empty;

    public string Model { get; set; } = string.Empty;
}
